package io.github.finalparadox.entity;
import io.github.finalparadox.registry.ModEntities;import net.minecraft.core.particles.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.protocol.Packet;import net.minecraft.network.protocol.game.ClientGamePacketListener;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.entity.*;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.phys.Vec3;import net.minecraftforge.network.NetworkHooks;import java.util.UUID;
public final class FrozenPrisonEntity extends Entity{public static final String FROZEN_TICKS="finalparadox.frozen_ticks",FREEZER="finalparadox.freezer";private UUID targetId;public FrozenPrisonEntity(EntityType<FrozenPrisonEntity>t,Level l){super(t,l);noPhysics=true;noCulling=true;}public static void freeze(LivingEntity target,net.minecraft.server.level.ServerPlayer owner){if(target.getPersistentData().getInt(FROZEN_TICKS)>0)return;target.getPersistentData().putInt(FROZEN_TICKS,80);target.getPersistentData().putUUID(FREEZER,owner.getUUID());FrozenPrisonEntity e=new FrozenPrisonEntity(ModEntities.FROZEN_PRISON.get(),target.level());e.targetId=target.getUUID();e.setPos(target.position());target.level().addFreshEntity(e);target.level().playSound(null,target.blockPosition(),net.minecraft.sounds.SoundEvents.IRON_GOLEM_DAMAGE,net.minecraft.sounds.SoundSource.PLAYERS,1,.5F);}
 @Override protected void defineSynchedData(){}@Override public void tick(){super.tick();if(level().isClientSide)return;if(!(level() instanceof ServerLevel s)){discard();return;}Entity raw=targetId==null?null:s.getEntity(targetId);if(!(raw instanceof LivingEntity target)||!target.isAlive()){if(raw instanceof LivingEntity target)clear(target);discard();return;}int ticks=target.getPersistentData().getInt(FROZEN_TICKS);if(ticks<=0){clear(target);discard();return;}target.getPersistentData().putInt(FROZEN_TICKS,ticks-1);target.setDeltaMovement(Vec3.ZERO);target.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN,2,10,true,false));setPos(target.position());s.sendParticles(new BlockParticleOption(ParticleTypes.FALLING_DUST,Blocks.SNOW_BLOCK.defaultBlockState()),target.getX(),target.getY()+1,target.getZ(),1,.2,.5,.2,0);}
 public static void clear(LivingEntity target){target.getPersistentData().remove(FROZEN_TICKS);target.getPersistentData().remove(FREEZER);}
 @Override protected void readAdditionalSaveData(CompoundTag t){if(t.hasUUID("Target"))targetId=t.getUUID("Target");}@Override protected void addAdditionalSaveData(CompoundTag t){if(targetId!=null)t.putUUID("Target",targetId);}@Override public Packet<ClientGamePacketListener>getAddEntityPacket(){return NetworkHooks.getEntitySpawningPacket(this);}}
